_choice_registry() {
    printf '%s\n' crates-io
    local file
    for file in "${CARGO_HOME:-$HOME/.cargo}/config.toml" "${CARGO_HOME:-$HOME/.cargo}/config" \
        ./.cargo/config.toml ./.cargo/config; do
        [[ -f "$file" ]] || continue
        gawk '/^\[registries\./ { line=$0; sub(/^\[registries\./, "", line); sub(/\]$/, "", line); print line }' "$file"
    done
}

_choice_target() {
    _argc_util_cache 3600 _helper_rustc_target_uncached rustc-target-list
}

_choice_version() {
    local crate="${argc_crate[0]:-}"
